<map version="1.0.1"><node CREATED="1747229317935" ID="ID_root" MODIFIED="1747229317935" TEXT="Day04_数组"><node CREATED="1747229317935" ID="ID_d75207964aff0b62" POSITION="right" MODIFIED="1747229317935" TEXT="学习方法的问题"><node CREATED="1747229317935" ID="ID_4d557e628b7a229d" MODIFIED="1747229317935" TEXT="上课应该好好学习。上课不光会讲一些知识，还会讲一些可能的坑。"><node CREATED="1747229317935" ID="ID_a0dba463d099e478" MODIFIED="1747229317935" TEXT="如果去公司了，现在写bug呢， 写出了问题。 怎么办？"></node><node CREATED="1747229317935" ID="ID_04030d224afe16fd" MODIFIED="1747229317935" TEXT="不要直接去问leader。 &amp;lt;br&amp;gt;1.应该首先尝试去解决这些问题。 比如打印、 debug 都是在发现bug。 &amp;lt;br&amp;gt;2.可以尝试用AI解决一下。 怀疑AI&amp;lt;br&amp;gt;3.可以去搜一下，之前别人碰到过没有。 CSDN、bing、stackOverflow、google&amp;lt;br&amp;gt;4.建议大家问问同事、同学、道友。 &amp;lt;br&amp;gt;5.leader。&amp;lt;br&amp;gt;"></node><node CREATED="1747229317935" ID="ID_8ab9db74ba80e2b6" MODIFIED="1747229317935" TEXT="&amp;quot;&amp;quot;&amp;quot;&amp;lt;br&amp;gt;代码&amp;lt;br&amp;gt;&amp;quot;&amp;quot;&amp;quot;&amp;lt;br&amp;gt;在引号里面的是我的代码。现在，我碰到了一个bug， 比如，现在我对sum预期的值是60，但是最终的结果是3。 帮我检查一下，为什么会出这个问题。&amp;lt;br&amp;gt;&amp;lt;br&amp;gt;int num;&amp;lt;br&amp;gt;scanf(&amp;quot;%d&amp;quot;, &amp;amp;num);&amp;lt;br&amp;gt;&amp;lt;br&amp;gt;*****"></node><node CREATED="1747229317935" ID="ID_f2b246532a7a068a" MODIFIED="1747229317935" TEXT="有一些问题可以直接问同事，&amp;lt;br&amp;gt;但是有一些建议自己先查查再问&amp;lt;br&amp;gt;"><node CREATED="1747229317935" ID="ID_2bdb7d67c72119c5" MODIFIED="1747229317935" TEXT="有没有一个好的分类方式。&amp;nbsp;怎么知道什么时候直接问，什么时候研究一下再问。&amp;nbsp;"></node><node CREATED="1747229317935" ID="ID_7b13f1e5b6c3a159" MODIFIED="1747229317935" TEXT="如果是一些环境问题，比如数据库怎么连，电脑怎么连。&amp;nbsp;互联网上搜不到的。&amp;nbsp;大概率是要要问才能知道的&amp;lt;br&amp;gt;"></node><node CREATED="1747229317935" ID="ID_56f8c4503314b418" MODIFIED="1747229317935" TEXT="有一些代码的bug问题，建议先搜索一下再问。&amp;nbsp;"></node></node></node><node CREATED="1747229317935" ID="ID_675f8f4efcb3ea20" MODIFIED="1747229317935" TEXT="晚自习的时候，要多敲代码，上课的代码需要敲一下"><node CREATED="1747229317935" ID="ID_c696e809c1c5a166" MODIFIED="1747229317935" TEXT="敲的时候，不要把我的代码放左边，自己的放右边。&amp;lt;br&amp;gt;直接照着敲。这样看起来是练习了，但是没达到练习的效果"></node></node><node CREATED="1747229317935" ID="ID_b4602c34c25d6243" MODIFIED="1747229317935" TEXT="学会看提示"><node CREATED="1747229317935" ID="ID_8ba29cddb5ff71bf" MODIFIED="1747229317935" TEXT="现在代码出错了。&amp;nbsp;程序出错了，建议看一下提示信息。&amp;nbsp;"><node CREATED="1747229317935" ID="ID_6239a9d4154cb16b" MODIFIED="1747229317935" TEXT="先大后小。 先说大的概念，然后让人在心中有一个大致的印象。 &amp;lt;br&amp;gt;&amp;lt;br&amp;gt;数组和链表。 &amp;lt;br&amp;gt;面试官问：简单介绍一下数组和链表。 怎么回答？&amp;lt;br&amp;gt;"></node></node></node></node><node CREATED="1747229317935" ID="ID_fdcd45b35cc3eefa" POSITION="right" MODIFIED="1747229317935" TEXT="概述"><node CREATED="1747229317935" ID="ID_728dca5e8183b064" MODIFIED="1747229317935" TEXT="数组是一个线性表。线性表，就是数据是一个接一个的。&amp;lt;br&amp;gt;数组是挨在一起的，每个位置存放的数据类型长度都一样"></node><node CREATED="1747229317935" ID="ID_f1e97f23f8ab0e65" MODIFIED="1747229317935" TEXT="回答问题的方式"><node CREATED="1747229317935" ID="ID_7a80d0d5b37d45d7" MODIFIED="1747229317935" TEXT="数组和链表，都是线性表， 线性表就是一个一对一的结构，一个数据后面跟着另一个数据。&amp;lt;br&amp;gt;数组是一块连续的内存空间。 链表是一个分散的内存空间，是靠一个一个的结点存数据，并且存下一个的地址。&amp;lt;br&amp;gt;增删改查。 增加，对于数组，需要挪动数据，将数据往后挪。 链表，只需要找到前驱结点，然后挪指针添加；&amp;lt;br&amp;gt;删除，对于数组， 需要把数据往前挪一位，然后最后那个删掉。 链表， 只需要找到前驱结点，挪指针&amp;lt;br&amp;gt;查，对于数组， 因为有随机访问的特性，所以可以直接得到该下标的地址，去地址取数据， 所以它的速度比较快。"></node></node><node CREATED="1747229317935" ID="ID_7b6cd5d64c03f48b" MODIFIED="1747229317935" TEXT="数组的优缺点"><node CREATED="1747229317935" ID="ID_69075b9a4256995e" MODIFIED="1747229317935" TEXT="数组的优缺点"></node><node CREATED="1747229317935" ID="ID_48c7f93234b948a1" MODIFIED="1747229317935" TEXT="链表的优缺点"></node></node><node CREATED="1747229317935" ID="ID_6f476dd7abbf1fb6" MODIFIED="1747229317935" TEXT="如果面试官问你数组和链表。"><node CREATED="1747229317935" ID="ID_2072fcf02d73cdfc" MODIFIED="1747229317935" TEXT="要听懂面试官的问题。&amp;nbsp;"></node></node></node><node CREATED="1747229317935" ID="ID_dc355ad9cd4fae7f" POSITION="right" MODIFIED="1747229317935" TEXT="使用"><node CREATED="1747229317935" ID="ID_af3ad7db88d4d3d9" MODIFIED="1747229317935" TEXT="声明"><node CREATED="1747229317935" ID="ID_db2fb28521de4a2b" MODIFIED="1747229317935" TEXT="语法&amp;lt;br&amp;gt;数据类型 数组名[数组的长度];"></node><node CREATED="1747229317935" ID="ID_68995fe1f235b7b9" MODIFIED="1747229317935" TEXT="int arr[5];&amp;lt;br&amp;gt;"></node><node CREATED="1747229317935" ID="ID_4980c9f0d1e234c1" MODIFIED="1747229317935" TEXT="注意"><node CREATED="1747229317935" ID="ID_60522408bd650700" MODIFIED="1747229317935" TEXT="长度只能是常量。&amp;lt;br&amp;gt;要么是字面值常量，要么是宏定义常量"></node><node CREATED="1747229317935" ID="ID_979d718637cbb758" MODIFIED="1747229317935" TEXT="const修饰也不行。const修饰的叫做只读变量，不叫常量"></node></node></node><node CREATED="1747229317935" ID="ID_32bce07ec579a4a5" MODIFIED="1747229317935" TEXT="初始化"><node CREATED="1747229317935" ID="ID_cab099c201fedcc8" MODIFIED="1747229317935" TEXT="给数组里面，初始化（第一次初始化）。&amp;lt;br&amp;gt;如果一个数组，没有手动初始化，里面的值是随机值"></node><node CREATED="1747229317935" ID="ID_6f7e8945075b20aa" MODIFIED="1747229317935" TEXT="数组初始化的方式&amp;lt;br&amp;gt;1.完整初始化&amp;lt;br&amp;gt;2.部分初始化&amp;lt;br&amp;gt;3.全部初始化为0"></node></node><node CREATED="1747229317935" ID="ID_685afd6f0031f0d3" MODIFIED="1747229317935" TEXT="数组的访问、修改。&amp;lt;br&amp;gt;坑&amp;lt;br&amp;gt;循环遍历"><node CREATED="1747229317935" ID="ID_363ba3f0d2d028b5" MODIFIED="1747229317935" TEXT="ARR_LEN"></node></node><node CREATED="1747229317935" ID="ID_7360ef480705cb5c" MODIFIED="1747229317935" TEXT="局部变量数组"><node CREATED="1747229317935" ID="ID_ebeec0416d995420" MODIFIED="1747229317935" TEXT="现在声明的数组，在局部变量位置。&amp;nbsp;&amp;lt;br&amp;gt;局部变量是存储在栈上。空间不是很大"><node CREATED="1747229317935" ID="ID_560f53244f09dc68" MODIFIED="1747229317935" TEXT="在申请大数组的时候，一定要小心。"></node><node CREATED="1747229317935" ID="ID_6b6b9bbff4f83825" MODIFIED="1747229317935" TEXT="一旦数组的长度超过了1000。不要在这上面申请了"></node></node></node></node><node CREATED="1747229317935" ID="ID_34fb945c2e4e13ad" POSITION="right" MODIFIED="1747229317935" TEXT="二维数组"><node CREATED="1747229317935" ID="ID_0636459697b788b5" MODIFIED="1747229317935" TEXT="概述"><node CREATED="1747229317935" ID="ID_4bc196ec13318cf4" MODIFIED="1747229317935" TEXT="要知道什么是二维数组：&amp;nbsp;装一维数组的数组。&amp;nbsp;"></node></node><node CREATED="1747229317935" ID="ID_083914e1d62702ac" MODIFIED="1747229317935" TEXT="二维数组的本质"><node CREATED="1747229317935" ID="ID_fb1da6674663b232" MODIFIED="1747229317935" TEXT="数学角度"><node CREATED="1747229317935" ID="ID_3dbdb000b381306a" MODIFIED="1747229317935" TEXT="矩阵"></node></node><node CREATED="1747229317935" ID="ID_b79ca991dbe5e21b" MODIFIED="1747229317935" TEXT="内存角度"><node CREATED="1747229317935" ID="ID_07b3b341ddb485c0" MODIFIED="1747229317935" TEXT="内存是连续的。&amp;nbsp;&amp;lt;br&amp;gt;随机访问。&amp;nbsp;寻址公式"></node></node></node></node><node CREATED="1747229317935" ID="ID_1526e3c4fb137055" POSITION="right" MODIFIED="1747229317935" TEXT="const"><node CREATED="1747229317935" ID="ID_7b6447173a423fab" MODIFIED="1747229317935" TEXT="是一个只读变量。&amp;lt;br&amp;gt;const int num = 10;&amp;lt;br&amp;gt;num = 888; //&amp;nbsp;改不了&amp;lt;br&amp;gt;scanf可以改"></node><node CREATED="1747229317935" ID="ID_efd92b0a30b281e2" MODIFIED="1747229317935" TEXT="防君子，不防小人&amp;nbsp;"></node><node CREATED="1747229317935" ID="ID_9829cc473e864581" MODIFIED="1747229317935" TEXT="使用const主要在一些不会被修改的地方。&amp;nbsp;"></node><node CREATED="1747229317935" ID="ID_15963efd8a436550" MODIFIED="1747229317935" TEXT="随机发牌"><node CREATED="1747229317935" ID="ID_e26c3599207f9a97" MODIFIED="1747229317935" TEXT="1.怎么在C语言中生成随机数。&amp;nbsp;"><node CREATED="1747229317935" ID="ID_2d2e2cf9e7c4e3b6" MODIFIED="1747229317935" TEXT="三个固定的步骤：&amp;lt;br&amp;gt;1.引入头文件 stdlib.h time.h&amp;lt;br&amp;gt;2.设置种子值srand(time(NULL))&amp;nbsp;&amp;nbsp;&amp;lt;br&amp;gt;3.调用rand()&amp;nbsp;得到随机数&amp;lt;br&amp;gt;"></node><node CREATED="1747229317935" ID="ID_3f69c4077d14221e" MODIFIED="1747229317935" TEXT="细节"><node CREATED="1747229317935" ID="ID_ede0dd8616a3476c" MODIFIED="1747229317935" TEXT="1.伪随机数。&amp;nbsp;种子值是固定的，得到的数据序列是固定的。"></node><node CREATED="1747229317935" ID="ID_bf192d5760b04d00" MODIFIED="1747229317935" TEXT="2.时间戳的概念"><node CREATED="1747229317935" ID="ID_24eb24f4c38fb53d" MODIFIED="1747229317935" TEXT="时间戳是一个通用的概念"></node></node><node CREATED="1747229317935" ID="ID_7f671913d4b16801" MODIFIED="1747229317935" TEXT="3.不要反复设置种子值"></node><node CREATED="1747229317935" ID="ID_6fbb92d35f3a3ba2" MODIFIED="1747229317935" TEXT="4.范围要知道一下。&amp;nbsp;"></node></node></node></node></node></node></map>